mapper.select:
SELECT PLACE_TYPE, ID, 3 AS sdType, DECODE( PLACE_TYPE, 0, DORMITORY_NAME || ROOM_NAME, 1, AREA_NAME, '' ) AS areaName, NAME AS deviceName, UPDATE_TIME FROM SMT_ELE_METER WHERE IS_DELETE = 0
and PLACE_TYPE = #{param.placeType}
and ID = #{param.deviceId}
UNION ALL SELECT PLACE_TYPE, ID, DECODE( LARGE_CLASS, 1, 1, 0, 2, 2 ) AS sdType, DECODE( PLACE_TYPE, 0, DORMITORY_NAME || ROOM_NAME, 1, AREA_NAME, '' ) AS areaName, NAME AS deviceName, UPDATE_TIME FROM SMT_WATER_METER WHERE IS_DELETE =0
and PLACE_TYPE = #{param.placeType}
and ID = #{param.deviceId}
order by UPDATE_TIME asc

SELECT se.PLACE_TYPE, se.ID, se.CONCENTRATOR_ID, 3 AS sdType, DECODE( se.PLACE_TYPE, 0, se.DORMITORY_NAME || se.ROOM_NAME, 1, se.AREA_NAME, '' ) AS areaName, se.NAME AS deviceName, se.ADDRESS, se.UPDATE_TIME, tag.TAG_NAME as deviceTag FROM SMT_ELE_METER se join SMT_ELE_METER_TAG setag ON se.id = setag.METER_ID join SMT_DEVICE_TAG tag on tag.ID = setag.TAG_ID WHERE se.IS_DELETE = 0
and se.AREA_ID = #{param.areaId}
and se.ID in
#{meterId}
UNION ALL SELECT sw.PLACE_TYPE, sw.ID, sw.CONCENTRATOR_ID, DECODE( sw.LARGE_CLASS, 1, 1, 0, 2, 2 ) AS sdType, DECODE( sw.PLACE_TYPE, 0, sw.DORMITORY_NAME || sw.ROOM_NAME, 1, sw.AREA_NAME, '' ) AS areaName, sw.NAME AS deviceName, sw.ADDRESS, sw.UPDATE_TIME, tag.TAG_NAME as deviceTag FROM SMT_WATER_METER sw join SMT_WATER_METER_TAG setag ON sw.id = setag.METER_ID join SMT_DEVICE_TAG tag on tag.ID = setag.TAG_ID WHERE sw.IS_DELETE =0
and sw.AREA_ID = #{param.areaId}
and sw.ID in
#{meterId}
order by UPDATE_TIME asc

