SELECT WATER_METER_ID as id, to_char( COLLECT_TIME, 'yyyy-mm' ) as month, MAX(CURRENT_READING) - MIN( CURRENT_READING ) as monthUse FROM SMT_WATER_METER_HISTORY WHERE WATER_METER_ID in
#{meterId}
AND COLLECT_TIME BETWEEN to_date( #{startTime}, 'yyyy-mm-dd hh24:mi:ss' ) AND to_date( #{endTime}, 'yyyy-mm-dd hh24:mi:ss' ) GROUP BY WATER_METER_ID, to_char( COLLECT_TIME, 'yyyy-mm' ) ORDER BY to_char( COLLECT_TIME, 'yyyy-mm' )

SELECT ELE_METER_ID as id, to_char( COLLECT_TIME, 'yyyy-mm' ) as month, MAX(CURRENT_READING) - MIN( CURRENT_READING ) as monthUse FROM SMT_ELE_METER_HISTORY WHERE ELE_METER_ID in
#{meterId}
AND COLLECT_TIME BETWEEN to_date( #{startTime}, 'yyyy-mm-dd hh24:mi:ss' ) AND to_date( #{endTime}, 'yyyy-mm-dd hh24:mi:ss' ) GROUP BY ELE_METER_ID, to_char( COLLECT_TIME, 'yyyy-mm' ) ORDER BY to_char( COLLECT_TIME, 'yyyy-mm' )

SELECT ELE_METER_ID as id, Min(COLLECT_TIME) as startDate, Max(COLLECT_TIME) as endDate, MIN(CURRENT_READING) as startNum, MAX(CURRENT_READING) as endNum, MAX(CURRENT_READING) - MIN(CURRENT_READING) as monthUse FROM SMT_ELE_METER_HISTORY WHERE ELE_METER_ID in
#{meterId}
AND COLLECT_TIME BETWEEN to_date( #{startTime}, 'yyyy-mm-dd hh24:mi:ss' ) AND to_date( #{endTime}, 'yyyy-mm-dd hh24:mi:ss' ) GROUP BY ELE_METER_ID, to_char( COLLECT_TIME, 'yyyy-mm' ) ORDER BY to_char( COLLECT_TIME, 'yyyy-mm' )
